<?php namespace App\Controllers; use App\Core\Controller; use App\Models\User;
final class AuthController extends Controller{public function showLogin():void{$this->view('auth/login');}public function login():void{$this->validateCsrf();$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$user=$email?User::findByEmail($email):null;if(!$user||!password_verify($_POST['password']??'',$user['password'])){flash('error','Email atau kata sandi tidak sesuai.');redirect('/login');}session_regenerate_id(true);$_SESSION['user']=['id'=>$user['id'],'name'=>$user['name'],'email'=>$user['email']];redirect('/dashboard');}public function showRegister():void{$this->view('auth/register');}public function register():void{$this->validateCsrf();$d=['name'=>trim($_POST['name']??''),'email'=>strtolower(trim($_POST['email']??'')),'phone'=>preg_replace('/\D/','',$_POST['phone']??''),'password'=>$_POST['password']??''];if(strlen($d['name'])<3||!filter_var($d['email'],FILTER_VALIDATE_EMAIL)||strlen($d['phone'])<9||strlen($d['password'])<8){flash('error','Periksa data. Nama min. 3 karakter, nomor min. 9 digit, kata sandi min. 8 karakter.');redirect('/register');}if(User::findByEmail($d['email'])){flash('error','Email sudah terdaftar.');redirect('/register');}$id=User::create($d);$_SESSION['user']=['id'=>$id,'name'=>$d['name'],'email'=>$d['email']];redirect('/dashboard');}public function logout():void{$this->validateCsrf();$_SESSION=[];session_destroy();redirect('/');}}
